import{M as e,U as t,W as n,it as r}from"./chunks/framework.B6iJhav1.js";var i=JSON.parse(`{"title":"开枪","description":"","frontmatter":{},"headers":[],"relativePath":"harmony/revolver/shooting.md","filePath":"harmony/revolver/shooting.md","lastUpdated":1786873544000}`),a={name:`harmony/revolver/shooting.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="shooting" tabindex="-1">开枪 <a class="header-anchor" href="#shooting" aria-label="Permalink to “开枪”">​</a></h1><p><strong>开枪 (Shooting)</strong> 是一个 <a href="/ZiYueBot/harmony/">鸿蒙命令</a>，可以在 <a href="/ZiYueBot/harmony/revolver/">俄罗斯轮盘</a> 游戏中，向自己或别人开枪。在调用该命令之前，必须先调用 <a href="./start">开始俄罗斯轮盘</a> 命令。</p><p>该命令会从当前膛室开始，逐个膛室进行击发，直到“子弹”击中玩家，或最后一个膛室被击发。该命令在有参数时会尝试解析提及的用户，并向其开枪。参数为空时则默认向自己开枪。</p><p><strong><a href="/ZiYueBot/timeline/#april">愚人节</a> 时，每次开枪都会击中玩家。</strong></p><p>该命令只能在群聊中调用。</p><h2 id="usage" tabindex="-1">用法 <a class="header-anchor" href="#usage" aria-label="Permalink to “用法”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/开枪 [user]</span></span></code></pre></div><h2 id="params" tabindex="-1">参数 <a class="header-anchor" href="#params" aria-label="Permalink to “参数”">​</a></h2><ul><li><code>user</code> 是可选参数，可用于指定开枪的目标。该参数必须为提及消息，否则无法正常调用。</li></ul><h2 id="output" tabindex="-1">输出 <a class="header-anchor" href="#output" aria-label="Permalink to “输出”">​</a></h2><ul><li><p>击中某人时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>砰！枪声响起，{用户} 倒下了</span></span></code></pre></div></li><li><p>没有击中时且还有剩余机会时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>咔哒，无事发生。轮盘中还剩 {剩余开枪机会} 个膛室。</span></span></code></pre></div></li><li><p>没有击中且没有剩余机会时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>咔哒，无事发生。轮盘中还剩 0 个膛室未击发。本局俄罗斯轮盘结束。</span></span></code></pre></div></li><li><p>游戏未开始时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>游戏未开始，发送“开始俄罗斯轮盘”来开始</span></span></code></pre></div></li><li><p>参数不为提及消息时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>参数无效。使用“/help 开枪”查看命令用法。</span></span></code></pre></div></li><li><p>调用频率达到限制时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>频率已达限制（每 3 秒 1 条）</span></span></code></pre></div></li></ul><h2 id="rate-limit" tabindex="-1">频率限制 <a class="header-anchor" href="#rate-limit" aria-label="Permalink to “频率限制”">​</a></h2><p>每次有效调用间隔不小于 3 秒。</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};